#!/bin/sh
# Writes .env with fresh secrets for the compose quickstart. Refuses to overwrite one.
set -eu
cd "$(dirname "$0")/../.."
if [ -e .env ]; then
  echo ".env already exists; leaving it alone" >&2
  exit 1
fi
umask 077
key=$(head -c 32 /dev/urandom | base64 | tr '+/' '-_' | tr -d '\n')
pw=$(head -c 24 /dev/urandom | base64 | tr -d '/+=\n')
cat > .env <<ENV
# Generated by deploy/compose/init.sh. Back up CAL_MIRROR_SECRET_KEY: without it the stored
# Google token and 2FA secrets cannot be read.
CAL_MIRROR_SECRET_KEY=$key
PG_PASSWORD=$pw
# Name you will type in the browser; must match the redirect URI in your Google OAuth client.
HOST_NAME=localhost
WEB_PORT=8443
# Interface the web app listens on. 127.0.0.1 = this machine only; use a LAN address to reach it
# from other machines. Do not expose it to the internet.
WEB_BIND=127.0.0.1
# Where archive files are written.
ARCHIVE_DIR=./archive
ENV
echo "wrote .env"
